{
  "name": "@fallroot/tada",
  "version": "0.2.4",
  "description": "Lightweight, no dependency library for lazy image load.",
  "author": "CK Moon <fallroot@gmail.com>",
  "main": "build/tada.js",
  "scripts": {
    "build": "webpack -p --config ./src/webpack.config.js"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/fallroot/tada"
  },
  "bugs": {
    "url": "https://github.com/fallroot/tada/issues"
  },
  "keywords": [
    "lazy",
    "load",
    "intersectionobserver"
  ],
  "devDependencies": {
    "@babel/core": "^7.0.1",
    "@babel/preset-env": "^7.0.0",
    "babel-loader": "^8.0.2",
    "standard": "12.0.1",
    "webpack": "^4.18.0",
    "webpack-cli": "^3.1.0"
  },
  "license": "MIT",
  "standard": {
    "env": {
      "browser": true
    },
    "ignore": [
      "/build/"
    ]
  }
}

import { detect } from './utils/detect'
import TadaWithIntersectionObserver from './intersection-observer'
import TadaWithLegacy from './legacy'

const tada = {
  setup (config) {
    const defaults = {
      attribute: 'data-src',
      delay: 50,
      threshold: '20%'
    }
    this.config = { ...defaults, config }
    this.useIntersectionObserver = detect()

    if (this.useIntersectionObserver) {
      this.instance = new TadaWithIntersectionObserver(this.config)
    } else {
      this.instance = new TadaWithLegacy(this.config)
    }
  },
  check () {
    if (!this.instance) {
      this.setup()
    }
  },
  add (element) {
    this.check()
    this.instance.add(element)
  },
  addContainer (element) {
    this.check()
    !this.useIntersectionObserver && this.instance.addContainer(element)
  },
  run () {
    this.check()
    !this.useIntersectionObserver && this.instance.run()
  }
}

export default tada

class Tada {
  constructor (config) {
    this.config = config
    this.init()
  }

  init () {
    this.observer = new IntersectionObserver((entries, observer) => {
      entries.forEach(this.execute.bind(this))
    }, {
      rootMargin: this.config.threshold
    })
  }

  add (element) {
    if (typeof element === 'string') {
      let nodes = document.querySelectorAll(element)

      for (let i = 0, length = nodes.length; i < length; ++i) {
        this.observer.observe(nodes[i])
      }
    } else {
      this.observer.observe(element)
    }
  }

  execute (entry) {
    if (!entry.isIntersecting) {
      return
    }

    const target = entry.target
    const tagName = target.tagName
    const src = target.getAttribute(this.config.attribute)

    if (tagName === 'IMG') {
      target.setAttribute('src', src)
    } else {
      target.style.backgroundImage = `url(${src})`
    }

    target.removeAttribute(this.config.attribute)
    this.observer.unobserve(target)

    if (typeof this.config.callback === 'function') {
      this.config.callback(target)
    }
  }
}

export default Tada

import debounce from '../utils/debounce'

class Tada {
  constructor (config) {
    this.config = config
    this.elements = []
  }

  setup (options) {
    if (this.initialized) {
      throw new Error('"setup" should be called before other methods.')
    }

    for (let key in options || {}) {
      this.config[key] = options[key]
    }
  }

  init () {
    if (this.initialized) {
      return
    }

    this.initialized = true

    this.applyDebounce()
    this.calcViewport()
    this.calcThreshold()
    this.bindEvents()
  }

  applyDebounce () {
    this.run = debounce(this.prepare.bind(this), this.config.delay)
  }

  calcViewport () {
    this.viewportHeight = window.innerHeight || document.documentElement.clientHeight
    this.viewportWidth = window.innerWidth || document.documentElement.clientWidth
  }

  calcThreshold () {
    let matches = this.config.threshold.toString().trim().match(/^(\d+)\s*(px|%)?$/i)

    if (!matches || !matches.length) {
      throw new Error('"threshold" value should be a number or "px" or "%".')
    }

    let value = matches[1]
    let unit = matches[2]

    if (unit === '%') {
      this.thresholdHeight = Math.floor(this.viewportHeight * value / 100)
      this.thresholdWidth = Math.floor(this.viewportWidth * value / 100)
    } else {
      this.thresholdHeight = this.thresholdWidth = value
    }
  }

  bindEvents () {
    window.addEventListener('scroll', this.onScroll.bind(this), false)
    window.addEventListener('resize', this.onResize.bind(this), false)
  }

  onScroll () {
    this.run()
  }

  onResize () {
    this.calcViewport()
    this.calcThreshold()
    this.run()
  }

  add (element) {
    this.init()

    if (typeof element === 'string') {
      let nodes = document.querySelectorAll(element)

      for (let i = 0, length = nodes.length; i < length; ++i) {
        this.addElement(nodes[i])
      }
    } else {
      this.addElement(element)
    }

    this.run()
  }

  addElement (element) {
    if (this.elements.indexOf(element) >= 0) {
      return
    }

    if (this.used(element)) {
      return
    }

    this.elements.push(element)
  }

  used (element) {
    let src = element.getAttribute(this.config.attribute)

    if (element.tagName === 'IMG') {
      if (element.getAttribute('src') === src) {
        return true
      }
    } else {
      if (element.style.backgroundImage === `url(${src})`) {
        return true
      }
    }

    return false
  }

  prepare () {
    let elements = this.elements.slice()

    for (let i = 0, length = elements.length; i < length; ++i) {
      let element = elements[i]

      if (!this.valid(element)) {
        continue
      }

      this.show(element)
    }
  }

  valid (element) {
    if (this.hidden(element)) {
      return false
    }

    let rect = element.getBoundingClientRect()
    let top = rect.top >= -this.thresholdHeight && rect.top <= this.viewportHeight + this.thresholdHeight
    let bottom = rect.bottom >= -this.thresholdHeight && rect.bottom <= this.viewportHeight + this.thresholdHeight
    let left = rect.left >= -this.thresholdWidth && rect.left <= this.viewportWidth + this.thresholdWidth
    let right = rect.right >= -this.thresholdWidth && rect.right <= this.viewportWidth + this.thresholdWidth

    return (top || bottom) && (left || right)
  }

  hidden (element) {
    return window.getComputedStyle(element).display === 'none'
  }

  show (element) {
    let src = element.getAttribute(this.config.attribute)

    if (element.tagName === 'IMG') {
      element.setAttribute('src', src)
    } else {
      element.style.backgroundImage = `url(${src})`
    }

    element.removeAttribute(this.config.attribute)

    this.elements.splice(this.elements.indexOf(element), 1)

    if (typeof this.config.callback === 'function') {
      this.config.callback(element)
    }
  }

  addContainer (selector) {
    if (!this.initialized) {
      this.init()
    }

    document.querySelectorAll(selector).forEach(element => {
      element.addEventListener('scroll', this.run)
    })
  }
}

export default Tada

export default function debounce (method, delay) {
  if (delay <= 0) {
    return method
  }

  let timer

  return function () {
    if (timer) {
      clearTimeout(timer)
    }

    timer = setTimeout(method, delay)
  }
}

export function detect () {
  return (
    'IntersectionObserver' in window &&
    'IntersectionObserverEntry' in window &&
    'isIntersecting' in window.IntersectionObserverEntry.prototype
  )
}

const path = require('path')

module.exports = {
  entry: path.resolve(__dirname, './index.js'),
  output: {
    filename: 'tada.js',
    library: 'Tada',
    libraryTarget: 'umd',
    path: path.resolve(__dirname, '../build')
  },
  module: {
    rules: [
      {
        exclude: [
          'node_modules',
          path.resolve(__dirname, '../tests')
        ],
        test: /\.js$/,
        use: {
          loader: 'babel-loader',
          options: {
            presets: ['@babel/preset-env']
          }
        }
      }
    ]
  }
}
